pub(crate) fn emit_is_variable(expr: &Expr, root: winnow_grammar::Symbol) -> bool {
    match expr {
        Expr::Variable(name, _) => { let name = *name; name == root },
        _ => false,
    }
}

pub(crate) fn emit_a_part_of(target: &Expr, root: winnow_grammar::Symbol) -> bool {
    match target {
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); emit_is_variable(base, root) || emit_a_part_of(base, root) },
        Expr::Index { base, .. } => { let base = nikaia_std::boxed::open(base); emit_is_variable(base, root) || emit_a_part_of(base, root) },
        _ => false,
    }
}

